<template>
  <div class="leetcode-body">
    <div class="boxD">
      <div style="height: 40px"/>
      <el-input
        v-model="searchWord" placeholder="" style="width: 300px" class="filter-item"
        size="medium"
        @clear="filter"  @keyup.enter.native="filter"  @click="filter"
      />
      <el-button id = 'searchButton'
        v-waves class="filter-item"
        size="medium"
        type="primary" icon="el-icon-search" style="margin-left: 10px; width: 90px;"
        @click="filter"
      >查询
      </el-button>
      <br/>

      <el-table
        :data="tableData"
        :show-header="false"
        fit
        highlight-current-row

        :row-style="{height: '0'}"
        :cell-style="{padding: '6px'}"
        >
        <el-table-column prop="id" label="id" min-width="30" align="center">
            <template slot-scope="{ row }">
              <el-button style="width: 29px; height: 29px;" circle size="mini" :type="getButtonType(row.id)">
                {{row.id}}
              </el-button>
            </template>
        </el-table-column>
        <el-table-column prop="category" label="分类" min-width="50" align="center" :show-overflow-tooltip="true"></el-table-column>
        <el-table-column prop="title" label="标题" min-width="100" align="left" :show-overflow-tooltip="true"></el-table-column>
        <el-table-column prop="star" label="star" min-width="50" align="center" :show-overflow-tooltip="true">
          <template slot-scope="{ row }">
            <i class="el-icon-star-on" v-for="i in row.star" style="color: red"></i>
          </template>
        </el-table-column>
      </el-table>

      <el-pagination
        style="margin-top: 23px"
        background
        layout="prev, pager, next"
        :total="total"
        :current-page.sync="listQuery.page"
        :page-size="9"
        @current-change="handleCurrentChange"
        >
      </el-pagination>
    </div>
  </div>
</template>

<script>
export default {
  name: 'Leetcode',
  components: {
  },
  data () {
    return {

      metaInfo: [],
      total: 0,
      listQuery: {},
      searchWord: "",
      pageSize: 9,
      tableData: []
    }
  },
  mounted() {
    this.load();
    this.filter(1, 10);
  },
  methods: {

    getButtonType(index) {
      var types = ['primary', 'success', 'warning', 'danger', 'info'];
      var mod = index % 5;
      return types[mod];
    },

      async load() {
         this.metaInfo = []
         this.tableData = []

         // 同步请求
         const xhr = new XMLHttpRequest();
         xhr.open('GET', '/static/page/leetcode/meta', false);
         xhr.send(null);

         if(xhr.readyState === 4 && xhr.status === 200) {
           var line = xhr.responseText.split("\n")
           for(var i = 0; i <= line.length - 2; i++) {
               var star = line[i].split("   ").length == 3 ? 1 : 0;
               this.metaInfo.push({id: i, category: line[i].split("   ")[0], title: line[i].split("   ")[1], star: star});
           }
         }
      },
      async filter(pageNum, pageSize) {
        pageNum = this.listQuery.page
        pageSize = this.pageSize
        if(pageNum === NaN) {
          pageNum = 1;
          pageSize = this.pageSize;
        }

        var metaInfo = this.metaInfo
        var start = (pageNum - 1) * pageSize
        var end = start + pageSize - 1
        if(end >= metaInfo.length - 1) {
          end = metaInfo.length - 1
        }

        // 根据搜索词过滤
        var searchWord = this.searchWord
        searchWord = searchWord.replace(/^\s*|\s*$/g,"");
        var meta = new Array();
        for(var i = 0; i <= metaInfo.length - 1; i++) {
            var line = metaInfo[i].category + metaInfo[i].title
            if(line.search(searchWord) > -1) {
              meta.push(metaInfo[i])
            }
        }
        var list = new Array()
        for(var i = start; i <= end; i++) {
          if(i > meta.length - 1) break;
          list.push({id: meta[i].id, category: meta[i].category, title: meta[i].title, star: meta[i].star});
        }
        const currentCount = list.length

        list.sort(
          (pre, cur) =>
            pre.id - cur.id
        )
        this.tableData = list
        this.total = meta.length
        this.listLoading = false
      },

      handleCurrentChange(val) {
        this.filter(val, 10);
      },

      getButtonType(index) {
        var types = ['primary', 'success', 'warning', 'danger', 'info'];
        var mod = index % 5;
        return types[mod];
      },

  }
}
</script>

<style>
  .leetcode-body {
      display: flex;
      justify-content: center;
      align-items: center;
      flex-wrap: wrap;
      border: 0px solid red;
  }

  .boxD {
    width: 900px;
    height: 550px;
    border: 2px solid white;
    font-size: 20px;
    border-radius: 20px;
    margin-top: 0px;
  }

  .el-table {
    border: 0px dashed white !important;
    border-radius: 0px !important;
    width: 720px !important;
    margin: 0 auto !important;
    margin-top: 30px !important;

    font-size: 15px !important;
    font-weight: bold !important;
    color: black !important;

    background-color: transparent !important;
  }

  .el-table__body-wrapper {
    tr {
      background-color: transparent !important;
    }
  }

  .el-table .el-table__header th,
  .el-table .el-table__body td {
    border: 0px !important;
    border-color: transparent !important; /* 去除边框 */
  }

  .el-table::before {
    background-color: transparent !important; /* 移除表格顶部和底部的边框线 */
  }

  .el-table td, .el-table th {
    border-bottom: 1px solid #ebeef5 !important; /* 自定义底部边框颜色 */
  }

  .el-table::after {
    border: 0px;
    background-color: transparent !important; /* 移除表格底部的边框线 */
  }

  /* 你的自定义CSS文件或<style>标签 */
  .el-button--info {
    background-color: #ff7f50 !important;
    border-color: #ff7f50 !important;
  }

  .el-button--success {
    background-color: #46cb18 !important;
    border-color: #46cb18 !important;
  }

</style>



