<template>
    <div class="main-layer">
      <div class="left-layer">

        <br/><br/>

        <center style="margin-left: 20px; margin-right: 20px;">
          <font color="#dd00dd" size=5 style="font-weight: normal;">
            how I met your mother
          </font>
        </center>

        <br/><br/><br/>

        <el-button class="ellipsis" style="width: 220px; max-width: 80%;" @click="handle('0416')" type="success">0416 Sorry Bro</el-button>
        <br/><br/>
        <el-button class="ellipsis" style="width: 220px; max-width: 80%;" @click="handle('0715')" type="warning">0715 The Burning beekeeper</el-button>
        <br/><br/>
        <el-button class="ellipsis" style="width: 220px; max-width: 80%;" @click="handle('0413')" type="info">0413 Three Days of Snow</el-button>

      </div>
      <div class="right-layer">
          <div id="detail" @wheel="getElementScrollProgress()" class="htmlContent" v-html="htmlContent">
          </div>
          <br />
          <el-progress style="margin-left: 100px; margin-right: 100px;" :stroke-width="20" :percentage="percentage" status="success"></el-progress>
      </div>
    </div>
</template>

<script>
import axios from 'axios';
export default {
  name: 'Note',
  components: {
  },
  props: ["message"],
  data () {
    return {
      htmlContent: "",
      percentage: 0
    }
  },
  mounted() {
    this.handle('0416');
  },
  methods: {
    async handle(i) {
        await axios.get("/static/page/himym/" + i + ".md").then(res =>{
            this.htmlContent = this.converter.makeHtml(res.data);
        })
    },

    getElementScrollProgress() {
        const element = document.getElementById('detail');
        const scrollTop = element.scrollTop;
        const clientHeight = element.clientHeight;
        const scrollHeight = element.scrollHeight;
        const scrollProgress = (scrollTop / (scrollHeight - clientHeight)) * 100;
        this.percentage = scrollProgress;
    }
  }
}
</script>

<style scoped>

@import url('https://fonts.googleapis.com/css2?family=Quicksand:wght@300;400;500;600;700&display=swap');

  .main-layer {
    width: 95%;
    height: 100%;

    border: 0px solid white;
    border-radius: 20px;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    gap: 12px;
  }

  .left-layer {
    width: 22%;
    height: 97%;
    border: 3px solid white;
    border-radius: 20px;
  }

  .right-layer {
    width: 73%;
    height: 97%;
    max-height: 97%;
    border: 3px solid white;
    border-radius: 20px;
    overflow: auto;
  }

  .htmlContent {
    text-align: left;
    margin-left: 30px;
    margin-right: 30px;
    margin-top: 3%;
    overflow-y:auto;
    height: 86%;
    font-size: 17px;
    color: black;
  }

  /* 自定义滚动条样式 */
  .htmlContent::-webkit-scrollbar {
    width: 1px; /* 设置滚动条宽度 */
  }

  .link-box {
     margin-left:0px;
     font-size: 17px;
     font-weight: bold;
     text-align: center;
     width: 100%;
     height: 50px;
     border: 0px solid white;
     padding: 0;
     border-radius: 1px;

     display: flex;
     justify-content: center;
     align-items: center;
     font-family: "Quicksand";
  }

  .link-box:hover {
      background-color: white; /* 鼠标悬浮时的背景色 */
      color: red;
      cursor: pointer;
  }

  .ellipsis {
    white-space: nowrap; /* 确保文本在一行内显示 */
    overflow: hidden; /* 隐藏溢出的内容 */
    text-overflow: ellipsis; /* 使用省略号表示溢出的文本 */
  }

  /* 你的自定义CSS文件或<style>标签 */
  .el-button--info {
    background-color: #ff7f50;
    border-color: #ff7f50;
  }

  .el-button--success {
    background-color: #46cb18;
    border-color: #46cb18;
  }
</style>



