<template>
  <div class="transcript-body">
    <div class="boxB" @click="handle(i)" v-for="(i, key) in data.length">
      <div class="row-1">
          <div class="col-11">
              <el-button style="width: 40px; height: 40px" circle :type="getButtonType(key)">{{data[key].id}}</el-button>
          </div>
          <div class="col-12">
              <p style="font-size: 17px; font-weight: bold; ">
                {{ data[key].title }}
                {{ data[key].subTitle }}
              </p>
          </div>
      </div>
      <div class="row-2">
        <p v-for="content in data[key].contents">
          {{ content }}
