            , "Robin: Morning, every body."
            , "All: Hey, Robin."
            , "Marshal: So you're actually doing it, huh? You're actually going to work at 2:00 a.m."
            , "Robin: I'm not doing it for me. I'm doing it for the fans.",
          ]
        },
        { id: 2, rate: 5, title: "how I met your mother - 0715", subTitle: "The Burning Beekeeper",
          contents: [
            "Lily: Dad, we need to talk.",
            "Micky: Is it about the bees?",
            "Marshal: Bees?",
            "Lily: We're throwing a housewarming party in two weeks.",
            "Micky: Oh.",
            "Lily: It's gonna be friends, neighbors...",
            "Marshal: Did he say... did he say 'bees' ?"
          ]
        },
        { id: 3, rate: 4, title: "the big bang theory - Series 02 Episode 07", subTitle: ""
          , contents: [
            "Penny (entering): Hey, guys, I need to use your TV.",
            "Sheldon: What’s wrong with your TV?",
            "Penny: I don’t know, it just died, I’m getting a bunch of static.",
            "Howard: Did you pay your cable bill?",
            "Penny: You sound just like the cable company. All right, so, shh, Tyra Banks is about to kick someone off  America’s Next Top Model.",
            "Sheldon: Excuse me, Penny, but we’re…"
          ]
        },
        { id: 4, rate: 4, title: "the big bang theory - Series 02 Episode 08", subTitle: ""
          , contents: [
            "Scene: The apartment.",
            "Sheldon: Oh look, Saturn 3 is on.",
            "Raj: I don’t want to watch Saturn 3. Deep Space Nine is better.",
            "Sheldon: How is Deep Space Nine better than Saturn 3?",
            "Raj: Simple subtraction will tell you it’s six better.",
            "Leonard: Compromise. Watch Babylon 5.",
            "Sheldon: In what sense is that a compromise?"
          ]
        },
        { id: 5, rate: 4, title: "friends - Season 08 Episode 01", subTitle: ""
          , contents: [
            "Photographer: Great. Great! Just give me a sec to change film.",
            "Monica: Okay.",
            "Ross: Okay, I know I’m not supposed to know, but I do. And I’m so excited for you!",
            "Joey: What? What’s going on?",
            "Ross: Monica’s pregnant!",
            "Joey: Oh my God! Is that why you guys had to get married?!",
            "Monica: Guys! I’m not pregnant."
          ]
        },
        { id: 6, rate: 4, title: "how I met your mother - S04E13 - Three Days of Snow", subTitle: ""
          , contents: [
            "Marshall: I'm not picking her up.",
            "Ted: What?",
            "Marshall: Lily doesn't want me taking a cab all the way to the airport just to take a cab all the way back, you know?",
            "Ted: But the six-pack thing.",
            "Marshall: Ted... that stuff was fun when we were younger, but we've grown past that. As we mature, the relationship matures with us.",
            "Ted: But..."
          ]
        }
      ]
    }
  },

  methods: {
    getButtonType(index) {
      var types = ['primary', 'success', 'warning', 'danger', 'info'];
      var mod = index % 5;
      return types[mod];
    },
  }

}
</script>

<style>

  .transcript-body {
    width: 100%;
    height: 500px;
    border: 0px solid black;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    flex-wrap: wrap;
    gap: 30px;
  }

  .boxB {
    width: 410px;
    height: 400px;
    border: 2px solid white;
    font-size: 20px;
    border-radius: 20px;
  }

  .row-1 {
     margin-top: 10px;
     margin-left: 30px;
     width: 360px;
     height: 70px;
     border: 0px solid red;

     display: flex;
     justify-content: align-start;
     align-items: center;
     gap: 20px;
     flex-wrap: wrap;
  }

  .col-11 {
    margin-left: 10px;
    width: 40px;
    border: 0px solid green;
  }

  .col-12 {
    margin-left: 0px;
    width: 250px;
    border: 0px solid green;
  }

  .row-2 {
    margin-top: 15px;
    margin-left: 30px;
    margin-right: 30px;
    width: 365px;
    height: 255px;
    border: 0px solid red;

    font-size: 17px;
    text-align: left;
  }

  .row-3 {
    margin-left: 20px;
    width: 360px;
    height: 50px;
    border: 0px solid red;

    display: flex;
    justify-content: center;
    align-items: center;
  }

  p {
    margin-top: 10px;
    margin-bottom: 10px;
  }

</style>



