<template>
  <el-container>
    <el-main>
      <leetcode v-if="visible[0]" />
      <transcript v-if="visible[1]" />
      <note v-if="visible[2]" />
      <note2 v-if="visible[3]" />
    </el-main>
    <el-aside width="120px">
      <div>
        <div class="box" v-for="(i, key) in 4" @click="handle(i)" @mouseover="handle(i)">
          <div class="test" :style="dynamicStyle(i)">
          </div>
        </div>
      </div>

    </el-aside>
  </el-container>
</template>

<script>
import Leetcode from './home/Leetcode';
import Transcript from './home/Transcript';
import Note from './home/Note';
import Note2 from './home/Note2';

export default {
  name: 'Page',
  data () {
    return {
      active: 1,
      visible: [true, false, false, false, false]
    }
  },
  components: {
    "leetcode": Leetcode,
    "transcript": Transcript,
    "note": Note,
    "note2": Note2
  },

  mounted() {
  },
  methods: {
    handle(i) {
      this.active = i;
      this.visible = [false, false, false, false, false]
      this.visible[i - 1] = true;
    },
    dynamicStyle(i) {
      if(this.active == i) {
        return {
          width: '22px',
          height: '22px'
        };
      } else {
        return {
          width: '10px',
          height: '10px'
        };
      }
    }
  }
}
</script>
<style scoped>
  .el-container {
    border: 0px solid white;
    width: 100%;
    height: 86%;
    position: fixed;
    overflow: auto;
  }

  .el-main {
    border: 0px solid red;
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: flex-start;
  }

  /* 自定义滚动条样式 */
  .el-main::-webkit-scrollbar {
    width: 10px; /* 设置滚动条宽度 */
  }

  .el-aside {
    border: 0px solid blue;
    display: flex;
    justify-content: center; /* 水平居中 */
    align-items: center;     /* 垂直居中 */
    height: 600px;
  }

  .box {
    width: 120px;
    height: 30px;
    display: flex;
    justify-content: center; /* 水平居中 */
    align-items: center;     /* 垂直居中 */
  }

  .test {
    width: 10px;
    height: 10px;
    background-color: #46cb18;
    border-radius: 50%;
    transition: background-color 0.5s ease; /* 定义过渡效果 */
  }

  .test:hover {
    width: 22px;
    height: 22px;
    background-color: #46cb18;
  }
</style>



