import Vue from 'vue'
import Router from 'vue-router'
import Home from '@/components/Home'
import CS from '@/components/CS'

Vue.use(Router)

export default new Router({
  routes: [
    {
      path: '/',
      name: 'Home',
      component: Home
    },
    {
     path: '/cs/:dir/:dir2',
     name: 'CS',
     component: CS
    },
  ]
})



