<template>
  <div class="main-layer">
    <div class="left-layer">

      <div style="color: black; font-family: 楷体;
        font-size: 18px; font-weight: bold; justify-content: center;
        margin-top: 25px; margin-bottom: 25px;
        white-space: nowrap; overflow: hidden; text-overflow: ellipsis; ">
        {{ this.titleMap[this.dir2] }} - {{ title }}
      </div>

      <el-button class="ellipsis" :type="getButtonType(i)" @click="handle(directoryList[i - 1][0]);updateTitle(i - 1);" v-for="(i, key) in directoryList.length" :key="key">
       {{ directoryList[i - 1][1] }}
      </el-button>
    </div>
    <div class="right-layer">
      <div id="detail" @wheel="getElementScrollProgress()" class="htmlContent" v-html="htmlContent">
      </div>
      <br />
      <el-progress style="margin-left: 100px; margin-right: 100px;" :stroke-width="20" :percentage="percentage" status="success"></el-progress>

    </div>
  </div>
</template>

<script>
import axios from 'axios';

export default {
  name: 'CS2',
  components: {

  },
  data () {
    return {
      htmlContent: "",
      percentage: 0,
      dir: "",
      dir2: "",
      directoryList: [],
      titleMap : {
        "base": "基础",

        "design-pattern": "设计模式",
        "algorithm": "算法导论",
        "interview": "面试题",
        "nginx": "nginx",
        "redis": "redis",
        "it-english": "IT英语",
        "vue": "vue",

        "spring-security": "权限管理",
        "java": "Java",
        "mybatis-plus": "mybatis-plus",
        "springboot": "springboot",
        "elasticsearch": "Elasticsearch",

        "threadpool": "线程池",
        "sharding-table": "分表",
        "sharding-db": "分库",
        "configuration": "配置",
        "ThreadLocal": "ThreadLocal",
        "mysql": "mysql",
        "mysql-index": "mysql - 索引",
        "sql-optimize": "SQL优化",
        "dubbo": "dubbo",
        "elasticsearch": "Elasticsearch",
        "elasticsearch-2": "Elasticsearch",

        "springboot": "springboot",
        "mybatis": "mybatis",
        "transaction": "事务",
        "aop": "SpringAOP",
        "mysql_docker": "mysql主从",
        "sharding": "分库分表",
        "restful": "restful",
        "docker": "docker",
        "https": "https",

        "logback": "logback",
        "jmeter": "jmeter",
        "kafka": "kafka",
        "python": "python",
        "elastic-job": "elastic-job",
        "maven": "maven",
        "react": "React",
        "react-2": "React",
        "easyexcel": "easyexcel",

        "nacos": "nacos",
        "openfeign": "openfeign",
        "gateway": "网关",
        "sentinel": "sentinel",
        "seata": "seata",
        "rabbitmq": "RabbitMQ",
        "jwt": "jwt",


        "leetcode": "算法",
        "leetcode2": "算法",
        "leetcode3": "算法",
        "leetcode4": "算法",
        "leetcode5": "算法",
        "leetcode6": "算法",
        "leetcode7": "算法",
        "leetcode8": "算法",
        "leetcode9": "算法",
        "other": "算法",

      },
      title : ""
    }
  },
  mounted() {
      var dir = this.$route.params.dir
      var dir2 = this.$route.params.dir2
      this.dir = dir;
      this.dir2 = dir2;
      this.getMeta(dir, dir2);
      this.handle(this.directoryList[0][0]);
      this.updateTitle(0);
  },
  watch : {
    $route() {
      var dir = this.$route.params.dir
      var dir2 = this.$route.params.dir2
      this.dir = dir;
      this.dir2 = dir2;
      this.getMeta(dir, dir2);
      this.handle(this.directoryList[0][0]);
      this.updateTitle(0);
    }
  },
  methods: {
    async getMeta(directory, directory2) {
      this.directoryList = []
      // 同步请求
      const xhr = new XMLHttpRequest();
      xhr.open('GET', '/static/cs/' + directory + '/' + directory2 + '/meta', false);
      xhr.send(null);

      if(xhr.readyState === 4 && xhr.status === 200) {
        var list = xhr.responseText.split("\n")
        for(var i = 0; i <= list.length - 2; i++) {
            var arr = [list[i].split(",")[0], list[i].split(",")[1]]
            this.directoryList.push(arr)
        }
      }
    },
    async handle(i) {
        var dir = this.$route.params.dir
        var dir2 = this.$route.params.dir2
        await axios.get("/static/cs/" + dir + '/' + dir2 + "/" +  i + ".md").then(res =>{
            this.htmlContent = this.converter.makeHtml(res.data);

            this.percent = 0
            const element = document.getElementById('detail');
            element.scrollTo({top: 0, behavior: 'instant'});
            this.getElementScrollProgress()
        })
    },
    updateTitle(i) {
      this.title = this.directoryList[i][1]
    },
    getButtonType(index) {
      var types = ['primary', 'success', 'warning', 'danger', 'info'];
      var mod = index % 5;
      return types[mod];
    },
    getElementScrollProgress() {
        const element = document.getElementById('detail');
        const scrollTop = element.scrollTop;
        const clientHeight = element.clientHeight;
        const scrollHeight = element.scrollHeight;
        const scrollProgress = (scrollTop / (scrollHeight - clientHeight)) * 100;
        this.percentage = scrollProgress;
    }
  }
}
</script>

<style scoped>

  .main-layer {
    width: 95%;
    height: 100%;
    max-height: 85%;

    border: 0px solid red;
    border-radius: 20px;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    gap: 12px;
    position: fixed;
  }

  .left-layer {
    width: 23%;
    height: 99%;
    border: 2px solid white;
    border-radius: 20px;
    overflow-y: auto;
  }

  /* 自定义滚动条样式 */
  .left-layer::-webkit-scrollbar {
    width: 0px; /* 设置滚动条宽度 */
  }

  .right-layer {
    width: 73%;
    height: 99%;
    max-height: 99%;
    border: 2px solid white;
    border-radius: 20px;
    overflow: auto;
  }

  .htmlContent {
    text-align: left;
    margin-left: 30px;
    margin-right: 30px;
    margin-top: 2%;
    overflow-y: auto;
    height: 86%;
    font-size: 18px;
    color: black;
    border: 0px solid blue;
  }

  /* 自定义滚动条样式 */
  .htmlContent::-webkit-scrollbar {
    width: 0px; /* 设置滚动条宽度 */
  }

  .el-button {
    width: 40%;
    height: 39px;
    margin-left: 20px;
    margin-right: 20px;
    margin: 8px;
  }

  .ellipsis {
    white-space: nowrap; /* 确保文本在一行内显示 */
    overflow: hidden; /* 隐藏溢出的内容 */
    text-overflow: ellipsis; /* 使用省略号表示溢出的文本 */
  }

  /* 你的自定义CSS文件或<style>标签 */
  .el-button--info {
    background-color: #ff7f50;
    border-color: #ff7f50;
  }

  .el-button--success {
    background-color: #46cb18;
    border-color: #46cb18;
  }
</style>



